package searchindex

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/billionairedev24/diaspora-commerce/go/pkg/meili"
)

// Meilisearch layout of the product read model: one index per market, uid = Alias(market) ("products-us"). The search
// and indexer services both build on these helpers so the settings and the document shape have one definition.

// MeiliEmbedder names the embedder that holds product vectors (supplied by the indexer, never generated by Meilisearch).
const MeiliEmbedder = "default"

// MeiliIndexUID is the market's index uid.
func MeiliIndexUID(market string) string { return Alias(market) }

// MeiliSettings is the product index configuration. Ranking is lexicographic (Meilisearch's rules apply in order), so
// the commercial signals Elasticsearch multiplies into the score become rules after text relevance:
//
//	sort            an explicit sort (price, rating, newest) wins; a no-op when the query has none
//	words           every query word must match (matchingStrategy "all"), last word as a prefix
//	in_stock_rank   in-stock products first among equally matching ones
//	typo ... exactness   Meilisearch's text relevance, fields ranked title, brand, category, description
//	rank_boost      fulfilled-by-AfroTransact, rating × review volume and fast delivery, computed by the indexer (MeiliBoost)
//
// synonyms nil leaves the index's synonyms as they are (the indexer ensures the index but does not own them).
func MeiliSettings(synonyms map[string][]string) map[string]any {
	settings := map[string]any{
		"searchableAttributes": []string{"title", "brand", "category_path", "description"},
		"filterableAttributes": []string{"status", "department", "communities", "fulfilment", "seller_kind", "seller_id", "rating",
			"price_minor", "delivery_days", "in_stock", "atin", "variant_atins", "has_embedding", "seller_name", "_geo"},
		"sortableAttributes": []string{"price_minor", "rating", "review_count", "updated_ts", "atin"},
		"rankingRules":       []string{"sort", "words", "in_stock_rank:desc", "typo", "proximity", "attribute", "exactness", "rank_boost:desc"},
		// Words of 4-7 letters may be one edit off, 8+ two. (Elasticsearch uses 3 and 6 with the first letter fixed;
		// Meilisearch cannot fix the first letter, so the thresholds are one letter higher to keep short words exact.)
		"typoTolerance": map[string]any{"enabled": true, "minWordSizeForTypos": map[string]int{"oneTypo": 4, "twoTypos": 8}},
		"faceting":      map[string]any{"maxValuesPerFacet": 50},
		"pagination":    map[string]any{"maxTotalHits": 5000},
		"embedders":     map[string]any{MeiliEmbedder: map[string]any{"source": "userProvided", "dimensions": EmbeddingDimensions}},
	}
	if synonyms != nil {
		settings["synonyms"] = synonyms
	}
	return settings
}

// MeiliEnsureIndex creates the market's index when it does not exist and applies the product settings. Settings are
// applied on every call (Meilisearch re-indexes only when something changed), so an index left half configured by an
// interrupted start is repaired on the next one.
func MeiliEnsureIndex(ctx context.Context, c *meili.Client, market string, synonyms map[string][]string) error {
	uid := MeiliIndexUID(market)
	err := c.Do(ctx, http.MethodGet, "/indexes/"+url.PathEscape(uid), nil, nil)
	if err != nil {
		if !meili.IsNotFound(err) {
			return fmt.Errorf("index %s: %w", uid, err)
		}
		if err := c.Task(ctx, http.MethodPost, "/indexes", map[string]any{"uid": uid, "primaryKey": "id"}); err != nil && !meili.IsCode(err, "index_already_exists") {
			return fmt.Errorf("create index %s: %w", uid, err)
		}
	}
	path := "/indexes/" + url.PathEscape(uid) + "/settings"
	err = c.Task(ctx, http.MethodPatch, path, MeiliSettings(synonyms))
	if meili.IsCode(err, "feature_not_enabled") {
		// Meilisearch before 1.13 keeps the vector store behind an experimental switch; turn it on and retry.
		if err := c.Do(ctx, http.MethodPatch, "/experimental-features", map[string]any{"vectorStore": true}, nil); err != nil {
			return fmt.Errorf("enable the vector store: %w", err)
		}
		err = c.Task(ctx, http.MethodPatch, path, MeiliSettings(synonyms))
	}
	if err != nil {
		return fmt.Errorf("settings %s: %w", uid, err)
	}
	return nil
}

// MeiliBoost is the commercial multiplier Elasticsearch applies as function scores, folded into one number the ranking
// rule rank_boost sorts by: fulfilled by AfroTransact ×1.2, 1 + 0.08 × rating × confidence (confidence =
// min(1, log10(1 + reviews) / 2)), delivery promised within 1-2 days ×1.05. Always ≥ 1, so nothing is ever zeroed.
func MeiliBoost(fulfilment string, rating float64, reviews, deliveryDays int) float64 {
	boost := 1.0
	if fulfilment == FulfilledByAfroTransact {
		boost *= 1.2
	}
	confidence := math.Min(1, math.Log10(1+float64(reviews))/2)
	boost *= 1 + 0.08*rating*confidence
	if deliveryDays >= 1 && deliveryDays <= 2 {
		boost *= 1.05
	}
	return math.Round(boost*10000) / 10000
}

// MeiliDocument turns a product document into the stored shape: the same fields plus the primary key, the geo point,
// the ranking helpers and, when present, the embedding as the default embedder's vector.
func MeiliDocument(doc ProductDocument) (map[string]any, error) {
	raw, err := json.Marshal(doc)
	if err != nil {
		return nil, fmt.Errorf("encode doc: %w", err)
	}
	m := map[string]any{}
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("decode doc: %w", err)
	}
	delete(m, "embedding")
	delete(m, "ships_from")
	m["id"] = doc.ATIN
	if doc.ShipsFrom != nil {
		m["_geo"] = map[string]float64{"lat": doc.ShipsFrom.Lat, "lng": doc.ShipsFrom.Lon}
	}
	if len(doc.Embedding) > 0 {
		m["_vectors"] = map[string]any{MeiliEmbedder: map[string]any{"embeddings": [][]float32{doc.Embedding}, "regenerate": false}}
		m["has_embedding"] = true
	} else {
		// A user-provided embedder insists every document either has a vector or opts out; the backfill adds it later.
		m["_vectors"] = map[string]any{MeiliEmbedder: nil}
	}
	MeiliDerive(m)
	return m, nil
}

// MeiliDerive recomputes the ranking helpers (in_stock_rank, rank_boost, updated_ts) from the document's own fields.
func MeiliDerive(m map[string]any) {
	inStock, _ := m["in_stock"].(bool)
	m["in_stock_rank"] = 0
	if inStock {
		m["in_stock_rank"] = 1
	}
	m["rank_boost"] = MeiliBoost(str(m["fulfilment"]), num(m["rating"]), int(num(m["review_count"])), int(num(m["delivery_days"])))
	if _, ok := m["has_embedding"]; !ok {
		m["has_embedding"] = false
	}
	if ts, ok := m["updated_at"].(string); ok {
		if t, err := time.Parse(time.RFC3339, ts); err == nil {
			m["updated_ts"] = t.Unix()
		}
	}
	if _, ok := m["updated_ts"]; !ok {
		m["updated_ts"] = time.Now().Unix()
	}
}

func str(v any) string {
	s, _ := v.(string)
	return s
}

func num(v any) float64 {
	switch n := v.(type) {
	case float64:
		return n
	case int:
		return float64(n)
	case int64:
		return float64(n)
	case json.Number:
		f, _ := n.Float64()
		return f
	}
	return 0
}

// MeiliNum reads a JSON number from a decoded document.
func MeiliNum(v any) float64 { return num(v) }

// MeiliStr reads a string from a decoded document.
func MeiliStr(v any) string { return strings.TrimSpace(str(v)) }
